// === Tab: Spot ===
class Spot {
	constructor(clr, eas = null) {
		const s = max(width, height);
		this.x = random(s * -0.25, s * 1.25);
		this.y = random(s * -0.25, s * 1.25);
		this.clr = color(clr);
		this.eas = eas;
		this.t = 0;
		this.dt = random(0.002, 0.004);
		this.isAlive = true;
	}

	update() {
		this.t += this.dt;
		if (this.t > 1) this.isAlive = false;
	}

	show() {
		if (!this.isAlive) return;

		const t = this.eas ? this.eas(this.t) : this.t;
		var s = t * width;
		const a = 2 * (0.5 - abs(this.t - 0.5)) * 200; // always stay a bit transparent
		this.clr.setAlpha(a);

		push();
		fill(this.clr);
		circle(this.x, this.y, s)
		pop();
	}
}

