const BG = "rgb(0, 0, 8)";
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);

let spots;

function setup() {
  createCanvas(400, 400); // createCanvas(windowWidth, windowHeight);
	describe("animation of circles, softly popping in and out with easing")
  frameRate(60);
  spots = [];
  noStroke();
	// console.log(random(Object.entries(easing)))
}

function draw() {
	background(BG);
  manageSpots(30, 20); // add and/or limit spots: every x-th frame, max spots

	// display spots
	for (let sp of spots) {
		sp.update();
		sp.show();
	}

  showTitle("#minacoding 2024/28: HitaHita"); // Write code that is HitaHita. (HitaHita is a Japanese onomatopoeia that means "softly" or "gently.")
}

function manageSpots(n, m) { // n: every n-th frame, m: max entries
	if (frameCount % n === 0 && spots.length < m) {
		const e = random(Object.entries(easing)); // 0: name, 1: func
		spots.push(new Spot(random(CLRS), e[1]));
	}
	spots = spots.filter((e) => e.t < 1);
}

function showTitle(msg) {
	push();
  stroke(0);
	strokeWeight(2);
  fill(255);
  text(msg, 2, 12);
  pop();
}
